fn test_adopt_moves_file_into_package() {
    let tmp = TempDir::new().unwrap();
    let home = TempDir::new().unwrap();
    // Create existing file at home/.gitconfig
    fs::write(home.path().join(".gitconfig"), "[user]\nname = test\n")
        .unwrap();
    // Create package dir (empty)
    fs::create_dir(tmp.path().join("git")).unwrap();
    // Write config pointing at home
    // adopt("git", &[".gitconfig"]) should:
    //   1. Move home/.gitconfig -> tmp/git/.gitconfig
    //   2. Create symlink home/.gitconfig -> tmp/git/.gitconfig
    //   3. Add state entry
}

/// Move existing files into a package and replace with symlinks
Adopt {
    /// Package to adopt files into
    package: String,
    /// File paths (relative to target dir) to adopt
    files: Vec<String>,
},

pub fn adopt_files(
    dotfiles_dir: &Path,
    config: &Config,
    state: &mut State,
    package: &str,
    files: &[String],
    opts: &LinkOptions,
    fs: &dyn FileStore,
    reporter: &dyn Reporter,
) -> Result<usize, NotfilesError> {
    let target_base = expand_tilde(config.target_for(package))?;
    let package_dir = dotfiles_dir.join(package);
    let mut adopted = 0;

    for file in files {
        let target = target_base.join(file);
        let source = package_dir.join(file);

        if !fs.exists(&target) {
            return Err(NotfilesError::Other(
                format!("{} does not exist", target.display()),
            ));
        }
        if fs.exists(&source) {
            return Err(NotfilesError::Conflict {
                path: source,
                reason: "already exists in package".into(),
            });
        }

        // Create parent dirs in package
        if let Some(parent) = source.parent().filter(|p| !fs.exists(p)) {
            fs.create_dir_all(parent)?;
        }

        if opts.dry_run {
            reporter.report(&LinkEvent::DryRun {
                action: "adopt",
                source: file,
                target: &target,
            });
            continue;
        }

        // Move target -> source (into package)
        fs.rename(&target, &source)?;
        // Symlink target -> source
        #[cfg(unix)]
        fs.symlink(&source, &target)?;

        state.add_entry(StateEntry {
            package: package.to_string(),
            source: source.to_string_lossy().to_string(),
            target: target.to_string_lossy().to_string(),
            method: Method::Symlink,
            linked_at: chrono::Utc::now().to_rfc3339(),
        });
        adopted += 1;
    }

    if !opts.dry_run {
        state.save(dotfiles_dir, fs)?;
    }
    Ok(adopted)
}

