#[test]
fn test_validate_suggests_typo_correction() {
    let available = vec!["git", "zsh", "nushell", "starship"];
    let config_name = "nushel"; // typo
    let suggestion = suggest_package(config_name, &available);
    assert_eq!(suggestion, Some("nushell"));
}

/// Suggest the closest package name if the user made a typo.
/// Returns None if no close match (distance > 2).
pub fn suggest_package<'a>(
    name: &str,
    available: &[&'a str],
) -> Option<&'a str> {
    available
        .iter()
        .filter_map(|candidate| {
            let dist = strsim::damerau_levenshtein(name, candidate);
            if dist <= 2 { Some((*candidate, dist)) } else { None }
        })
        .min_by_key(|(_, d)| *d)
        .map(|(name, _)| name)
}

