#[test]
fn secret_resolver_resolves_env_var_cross_crate() {
    use notsecrets::config::{Provider, SecretsConfig};
    use notsecrets::resolver::SecretResolver;
    use std::collections::HashMap;

    unsafe { std::env::set_var("NOTFILES_CROSS_CRATE_TEST", "works"); }

    let config = SecretsConfig {
        providers: vec![Provider::Env],
        provider: HashMap::new(),
        secrets: HashMap::new(),
    };
    let resolver = SecretResolver::from_config(config).unwrap();
    let val = resolver.resolve("NOTFILES_CROSS_CRATE_TEST").unwrap();
    assert_eq!(val, Some("works".to_string()));

    unsafe { std::env::remove_var("NOTFILES_CROSS_CRATE_TEST"); }
}

pub struct BootstrapOptions {
    pub config: PathBuf,
    pub force: bool,
    pub key_file: Option<PathBuf>,
    pub dotfiles: Option<PathBuf>,
    /// Optional override for the sops decrypt step.
    /// None = skip env injection (used in tests).
    /// Some(f) = call f(sops_path) and inject the result into env.
    pub env_injector: Option<Box<dyn Fn(&Path) -> anyhow::Result<String>>>,
}

pub fn run(opts: BootstrapOptions) -> anyhow::Result<Report>

fn main() -> Result<()> {
    let cli = Cli::parse();
    let Cmd::Run { config, force, key_file, dotfiles } = cli.command;
    let opts = BootstrapOptions {
        config, force, key_file, dotfiles,
        env_injector: Some(Box::new(|p| notsecrets::decrypt_sops(p))),
    };
    let report = notstrap::run(opts)?;
    if report.has_failures() { std::process::exit(1); }
    Ok(())
}

